USE [JamunaBankProcurement];
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementAuthority_GetPending @EmployeeId VARCHAR(30) AS BEGIN SET NOCOUNT ON; IF NOT EXISTS(SELECT 1 FROM dbo.PROC_AUTHORITY WHERE EMPLOYEE_ID=@EmployeeId AND IS_ACTIVE=1 AND EFFECTIVE_FROM<=CONVERT(DATE,SYSUTCDATETIME()) AND (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>=CONVERT(DATE,SYSUTCDATETIME()))) RETURN; SELECT h.REQUISITION_ID,h.REQUISITION_NO,h.TOTAL_ESTIMATED_AMOUNT FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.REQUISITION_HEADER h ON h.REQUISITION_ID=w.REQUISITION_ID WHERE w.CURRENT_STAGE='PROCUREMENT_AUTHORITY' AND w.COMPLETED_DATE IS NULL; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementAuthority_Approve @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000)=NULL,@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN DECLARE @next VARCHAR(40)=(SELECT CASE WHEN r.CONCERN_DIVISION_ID IS NOT NULL AND r.AUTHORITY_BEFORE_DIVISION=1 AND NOT EXISTS(SELECT 1 FROM dbo.WORKFLOW_HISTORY h WHERE h.REQUISITION_ID=@RequisitionId AND h.TO_STAGE='CONCERN_DIVISION') THEN 'CONCERN_DIVISION' ELSE 'READY_FOR_PROCUREMENT' END FROM dbo.WORKFLOW_INSTANCE w JOIN dbo.WORKFLOW_RULE r ON r.WORKFLOW_RULE_ID=w.WORKFLOW_RULE_ID WHERE w.REQUISITION_ID=@RequisitionId AND w.COMPLETED_DATE IS NULL); EXEC dbo.usp_Workflow_Advance @RequisitionId,@ActorEmployeeId,'PROCUREMENT_AUTHORITY','PROCUREMENT_AUTHORITY_APPROVE','PROCUREMENT_AUTHORITY',@next,@Remarks,@BatchReferenceId; END;
GO
CREATE OR ALTER PROCEDURE dbo.usp_ProcurementAuthority_Reject @RequisitionId BIGINT,@ActorEmployeeId VARCHAR(30),@Remarks NVARCHAR(2000),@BatchReferenceId UNIQUEIDENTIFIER=NULL AS BEGIN EXEC dbo.usp_Workflow_SimpleTerminal @RequisitionId,@ActorEmployeeId,'PROCUREMENT_AUTHORITY','IN_WORKFLOW','PROCUREMENT_AUTHORITY_REJECT','REJECTED','END',@Remarks,@BatchReferenceId; END;
GO

